import { Component, inject, input, signal, effect, DestroyRef, OnDestroy } from '@angular/core';
import { DomSanitizer, SafeResourceUrl } from '@angular/platform-browser';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { HttpClient, HttpResponse } from '@angular/common/http';
import { Subject, switchMap, EMPTY } from 'rxjs';
import { environment } from '../../../../environments/environment';

type LoadRequest =
  | { type: 'url'; url: string; nombre: string | null }
  | { type: 'id'; id: number; nombre: string | null }
  | { type: 'none' };

function inferMimeType(nameOrUrl: string): string {
  const lower = nameOrUrl.toLowerCase();
  if (lower.endsWith('.pdf')) return 'application/pdf';
  if (lower.endsWith('.png')) return 'image/png';
  if (lower.endsWith('.jpg') || lower.endsWith('.jpeg')) return 'image/jpeg';
  if (lower.endsWith('.gif')) return 'image/gif';
  if (lower.endsWith('.webp')) return 'image/webp';
  if (lower.endsWith('.svg')) return 'image/svg+xml';
  return 'application/pdf';
}

@Component({
  selector: 'app-pdf-viewer',
  templateUrl: './pdf-viewer.component.html',
  host: { class: 'd-block' },
})
export class PdfViewerComponent implements OnDestroy {
  private readonly sanitizer = inject(DomSanitizer);
  private readonly http = inject(HttpClient);
  private readonly destroyRef = inject(DestroyRef);

  readonly documentoId = input<number | null>(null);
  readonly url = input<string | null>(null);
  readonly nombreOriginal = input<string | null>(null);

  readonly loading = signal(true);
  readonly error = signal(false);
  readonly blobUrl = signal<SafeResourceUrl | null>(null);
  readonly rawBlobUrl = signal<string | null>(null);
  readonly contentType = signal<string>('application/pdf');
  readonly fileName = signal<string>('documento.pdf');
  private readonly loadRequest$ = new Subject<LoadRequest>();

  get isImage(): boolean {
    return this.contentType().startsWith('image/');
  }

  get isPdf(): boolean {
    const type = this.contentType();
    return type === 'application/pdf' || this.fileName().toLowerCase().endsWith('.pdf');
  }

  constructor() {
    this.loadRequest$
      .pipe(
        switchMap((req) => {
          if (req.type === 'url') {
            const nombre = req.nombre || req.url;
            const mime = inferMimeType(nombre);
            this.contentType.set(mime);
            this.fileName.set(req.nombre || this.buildNameFromUrl(req.url));
            this.rawBlobUrl.set(req.url);
            this.blobUrl.set(this.sanitizer.bypassSecurityTrustResourceUrl(req.url));
            this.loading.set(false);
            return EMPTY;
          }

          if (req.type === 'id') {
            return this.http.get(`${environment.apiUrl}/documentos/${req.id}`, {
              responseType: 'arraybuffer',
              observe: 'response',
            });
          }

          this.loading.set(false);
          this.error.set(true);
          return EMPTY;
        }),
        takeUntilDestroyed(this.destroyRef),
      )
      .subscribe({
        next: (response: HttpResponse<ArrayBuffer>) => {
          const mimeType = response.headers.get('content-type') || 'application/pdf';
          this.contentType.set(mimeType);

          const contentDisposition = response.headers.get('content-disposition');
          let parsedName = this.nombreOriginal() || 'documento';
          if (contentDisposition) {
            const match = contentDisposition.match(/filename="?([^";]+)"?/i);
            if (match && match[1]) {
              parsedName = match[1];
            }
          }
          this.fileName.set(parsedName);

          const blob = new Blob([response.body as ArrayBuffer], { type: mimeType });
          const objectUrl = URL.createObjectURL(blob);
          this.revokePreviousBlobUrl();
          this.rawBlobUrl.set(objectUrl);
          this.blobUrl.set(this.sanitizer.bypassSecurityTrustResourceUrl(objectUrl));
          this.loading.set(false);
        },
        error: () => {
          this.loading.set(false);
          this.error.set(true);
        },
      });

    effect(() => {
      this.dispatch();
    });
  }

  ngOnDestroy(): void {
    this.loadRequest$.complete();
    this.revokePreviousBlobUrl();
  }

  private revokePreviousBlobUrl(): void {
    const prev = this.rawBlobUrl();
    if (prev?.startsWith('blob:')) {
      URL.revokeObjectURL(prev);
    }
  }

  recargar(): void {
    this.dispatch();
  }

  private dispatch(): void {
    const directUrl = this.url();
    const docId = this.documentoId();
    const nombre = this.nombreOriginal();

    this.loading.set(true);
    this.error.set(false);

    if (directUrl) {
      this.loadRequest$.next({ type: 'url', url: directUrl, nombre });
    } else if (docId != null) {
      this.loadRequest$.next({ type: 'id', id: docId, nombre });
    } else {
      this.loadRequest$.next({ type: 'none' });
    }
  }

  private buildNameFromUrl(url: string): string {
    const segment = url.split('/').at(-1)?.split('?')[0] ?? '';
    return segment.includes('.') ? segment : 'documento';
  }

  descargar(): void {
    const rawUrl = this.rawBlobUrl();
    if (!rawUrl) return;
    const a = document.createElement('a');
    a.href = rawUrl;
    a.download = this.fileName();
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  }

  abrirEnPestana(): void {
    const rawUrl = this.rawBlobUrl();
    if (rawUrl) {
      window.open(rawUrl, '_blank', 'noopener,noreferrer');
    }
  }
}
